/** Merges an array of objects into one object, as some servers send objects and maps. */
private fun foldObjects(element: JsonElement): JsonElement = when (element) {
    is JsonArray -> JsonObject(element.filterIsInstance<JsonObject>().flatMap { it.entries }.associate { it.key to it.value })
    else -> element
}

/**
 * Appends [value] as PHP-style bracketed fields named after [name] (`name[0][key]=value`), as
 * PHP servers read lists and records. Booleans are written `1` and `0`; nulls are left out.
 */
internal fun ParametersBuilder.appendBrackets(name: String, value: JsonElement) {
    when (value) {
        is JsonObject -> value.forEach { (key, item) -> appendBrackets("$name[$key]", item) }
        is JsonArray -> value.forEachIndexed { index, item -> appendBrackets("$name[$index]", item) }
        JsonNull -> Unit
        is JsonPrimitive -> append(name, value.takeUnless { it.isString }?.booleanOrNull?.let { if (it) "1" else "0" } ?: value.content)
    }
}
